using Rhino;using Rhino.PlugIns;using Rhino.UI;
namespace RhinoContextAssist;
public sealed class ContextAssistPlugIn:PlugIn{internal static ContextAssistPlugIn? Instance{get;private set;}internal ContextAssistSettings SettingsModel{get;private set;}=null!;ContextAssistController? controller;public ContextAssistPlugIn()=>Instance=this;protected override LoadReturnCode OnLoad(ref string e){SettingsModel=new(Settings);controller=new(SettingsModel);controller.Start();RhinoApp.WriteLine("Rhino Context Assist Hybrid HUD 2.0 geladen.");return LoadReturnCode.Success;}protected override void OptionsDialogPages(List<OptionsDialogPage> pages)=>pages.Add(new ContextAssistOptionsPage(SettingsModel,()=>controller?.Refresh()));protected override void OnShutdown()=>controller?.Dispose();}
